#!/bin/zsh
set -euo pipefail
task_root="${0:A:h}"
task_cache="$task_root/.build/test-module-cache"
mkdir -p "$task_cache"
xcrun swiftc -swift-version 5 -parse-as-library -module-cache-path "$task_cache" "$task_root/Dock/Configuration.swift" "$task_root/Tests/ConfigurationTests.swift" -o "$task_root/.build/configuration-tests"
"$task_root/.build/configuration-tests"
task_core="$task_root/ThirdParty/DockLock-source/DockLockCore/Sources/DockLockCore"
if [[ ! -d "$task_core" ]]; then task_core="$task_root/../docklock-upstream/DockLockCore/Sources/DockLockCore"; fi
xcrun swiftc -swift-version 5 -parse-as-library -module-cache-path "$task_cache" "$task_core/"*.swift "$task_root/Tests/EdgeGuardTests.swift" -o "$task_root/.build/edge-tests"
"$task_root/.build/edge-tests"
xcrun swiftc -swift-version 5 -parse-as-library -module-cache-path "$task_cache" "$task_root/Dock/TrashState.swift" "$task_root/Tests/TrashStateTests.swift" -o "$task_root/.build/trash-tests"
"$task_root/.build/trash-tests"
xcrun swiftc -swift-version 5 -parse-as-library -module-cache-path "$task_cache" "$task_root/Shared/WindowIntent.swift" "$task_root/Shared/WindowProtocol.swift" "$task_root/Dock/DockResize.swift" "$task_root/Tests/WindowBehaviorTests.swift" -o "$task_root/.build/window-tests"
"$task_root/.build/window-tests"
node "$task_root/Tests/WindowLayoutTests.js"
xcrun swiftc -swift-version 5 -parse-as-library -module-cache-path "$task_cache" "$task_root/Dock/QuitSessionLease.swift" "$task_root/Tests/QuitSessionTests.swift" -o "$task_root/.build/quit-session-tests"
"$task_root/.build/quit-session-tests"
xcrun swiftc -swift-version 5 -parse-as-library -module-cache-path "$task_cache" "$task_root/Dock/Configuration.swift" "$task_root/Dock/QuitSessionLease.swift" "$task_root/Dock/QuitService.swift" "$task_root/Tests/QuitServiceTests.swift" -o "$task_root/.build/quit-service-tests"
"$task_root/.build/quit-service-tests"
xcrun swiftc -swift-version 5 -parse-as-library -module-cache-path "$task_cache" "$task_root/Controls/QuitControlIntent.swift" "$task_root/Tests/QuitControlDispatchTests.swift" -o "$task_root/.build/quit-control-dispatch-tests"
"$task_root/.build/quit-control-dispatch-tests"
xcrun swiftc -swift-version 5 -parse-as-library -module-cache-path "$task_cache" "$task_root/Shared/DirectoryEvents.swift" "$task_root/Tests/DirectoryEventsTests.swift" -o "$task_root/.build/directory-event-tests"
"$task_root/.build/directory-event-tests"
xcrun swiftc -swift-version 5 -parse-as-library -module-cache-path "$task_cache" "$task_root/Dock/Configuration.swift" "$task_root/Shared/CopiedApplicationMenu.swift" "$task_root/Tests/MenuCopyTests.swift" -o "$task_root/.build/menu-copy-tests"
"$task_root/.build/menu-copy-tests"
